-- Schema-only reproduction of in-scope FRONTAL SLAYER tables, from a read-only catalog query of
-- project hyycomvcaqxxvyrfupes on 2026-10-26 (pg_attribute / pg_constraint). No rows copied.
-- Foreign keys to auth.users are omitted (local rehearsal has a minimal auth schema).
CREATE TABLE public.consult_quotes (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, client_email text, unit_key text, selections jsonb DEFAULT '{}'::jsonb, price_breakdown jsonb DEFAULT '[]'::jsonb, admin_message text, thumbnail_src text, discount_code text NOT NULL, discount_amount_usd integer NOT NULL DEFAULT 40, expires_at timestamp with time zone NOT NULL, created_at timestamp with time zone DEFAULT now(), redeemed_at timestamp with time zone, CONSTRAINT consult_quotes_pkey PRIMARY KEY (id));
CREATE TABLE public.hairstyle_analysis_purchase_grants (stripe_payment_intent_id text NOT NULL, user_id uuid NOT NULL, granted_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT hairstyle_analysis_purchase_grants_pkey PRIMARY KEY (stripe_payment_intent_id));
CREATE TABLE public.hairstyle_analysis_usage (user_id uuid NOT NULL, month_key text NOT NULL DEFAULT ''::text, month_count integer NOT NULL DEFAULT 0, updated_at timestamp with time zone NOT NULL DEFAULT now(), paid_credit_queue integer[] NOT NULL DEFAULT '{}'::integer[], CONSTRAINT hairstyle_analysis_usage_month_count_check CHECK ((month_count >= 0)), CONSTRAINT hairstyle_analysis_usage_pkey PRIMARY KEY (user_id));
CREATE TABLE public.lounge_engagement_comments (id uuid NOT NULL DEFAULT gen_random_uuid(), content_type text NOT NULL, content_id text NOT NULL, user_id uuid NOT NULL, parent_id uuid, body text NOT NULL, status text NOT NULL DEFAULT 'visible'::text, is_official boolean NOT NULL DEFAULT false, is_pinned boolean NOT NULL DEFAULT false, pinned_at timestamp with time zone, pinned_by uuid, report_count integer NOT NULL DEFAULT 0, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), deleted_at timestamp with time zone, CONSTRAINT lounge_engagement_comments_pkey PRIMARY KEY (id), CONSTRAINT lounge_engagement_comments_status_check CHECK ((status = ANY (ARRAY['visible'::text, 'hidden'::text, 'removed'::text, 'pending'::text]))));
CREATE TABLE public.lounge_engagement_helpful (content_type text NOT NULL, content_id text NOT NULL, user_id uuid NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT lounge_engagement_helpful_pkey PRIMARY KEY (content_type, content_id, user_id));
CREATE TABLE public.lounge_engagement_qualified_views (id uuid NOT NULL DEFAULT gen_random_uuid(), content_type text NOT NULL, content_id text NOT NULL, user_id uuid, viewer_key text, watch_seconds integer NOT NULL DEFAULT 0, qualified_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT lounge_engagement_qualified_views_pkey PRIMARY KEY (id), CONSTRAINT lounge_engagement_qualified_views_watch_seconds_check CHECK ((watch_seconds >= 0)), CONSTRAINT lounge_engagement_qv_identity_chk CHECK (((user_id IS NOT NULL) OR (viewer_key IS NOT NULL))));
CREATE TABLE public.lounge_engagement_summaries (content_type text NOT NULL, content_id text NOT NULL, qualified_view_count integer NOT NULL DEFAULT 0, helpful_count integer NOT NULL DEFAULT 0, comment_count integer NOT NULL DEFAULT 0, updated_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT lounge_engagement_summaries_pkey PRIMARY KEY (content_type, content_id));
CREATE TABLE public.meetings (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, client_email text, client_name text, meeting_date date NOT NULL, meeting_time time without time zone, type text NOT NULL DEFAULT 'Consultation'::text, duration_minutes integer DEFAULT 60, status text NOT NULL DEFAULT 'scheduled'::text, notes text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), category text NOT NULL DEFAULT 'appointment'::text, metadata jsonb DEFAULT '{}'::jsonb, CONSTRAINT meetings_pkey PRIMARY KEY (id), CONSTRAINT meetings_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'confirmed'::text, 'completed'::text, 'cancelled'::text, 'pending'::text]))));
CREATE TABLE public.membership_payments (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, user_email text, stripe_invoice_id text NOT NULL, stripe_subscription_id text, stripe_customer_id text, subscription_tier text, amount_usd numeric(12,2) NOT NULL, currency text NOT NULL DEFAULT 'usd'::text, kind text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), billing_period_end timestamp with time zone, CONSTRAINT membership_payments_kind_check CHECK ((kind = ANY (ARRAY['initial'::text, 'renewal'::text]))), CONSTRAINT membership_payments_pkey PRIMARY KEY (id), CONSTRAINT membership_payments_stripe_invoice_id_key UNIQUE (stripe_invoice_id));
CREATE TABLE public.notifications (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, items jsonb DEFAULT '[]'::jsonb, updated_at timestamp with time zone DEFAULT now(), CONSTRAINT notifications_pkey PRIMARY KEY (id), CONSTRAINT notifications_user_id_key UNIQUE (user_id));
CREATE TABLE public.orders (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, email text NOT NULL, active_orders jsonb DEFAULT '[]'::jsonb, past_orders jsonb DEFAULT '[]'::jsonb, updated_at timestamp with time zone DEFAULT now(), CONSTRAINT orders_pkey PRIMARY KEY (id));
CREATE SEQUENCE public.profile_debug_log_id_seq;
CREATE TABLE public.profile_debug_log (id bigint NOT NULL DEFAULT nextval('profile_debug_log_id_seq'::regclass), profile_id uuid, email text, old_first_name text, new_first_name text, old_last_name text, new_last_name text, old_profile_image text, new_profile_image text, changed_at timestamp with time zone DEFAULT now(), CONSTRAINT profile_debug_log_pkey PRIMARY KEY (id));
CREATE TABLE public.profiles (id uuid NOT NULL, email text NOT NULL, role text, first_name text, last_name text, phone_number text, birthday text, facebook text, instagram text, youtube text, tiktok text, twitter text, profile_image text, membership_type text, subscription_tier text, default_address jsonb, shipping_address jsonb, saved_addresses jsonb, referral_code text, gift_card_balance numeric DEFAULT 0, has_made_first_purchase boolean DEFAULT false, loyalty_points integer DEFAULT 0, unlocked_discounts jsonb, voucher_list jsonb, voucher_history jsonb, digital_cash_history jsonb, welcome_discount_tiers_credited_by_period jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), current_tier_name text, notification_newsletter boolean NOT NULL DEFAULT true, notification_sales boolean NOT NULL DEFAULT true, notification_order_tracking boolean NOT NULL DEFAULT true, stripe_customer_id text, stripe_subscription_id text, auto_renew_membership boolean DEFAULT true, subscription_period_end timestamp with time zone, subscription_purchased_at timestamp with time zone, stripe_subscription_status text, last_payment_failure_at timestamp with time zone, stripe_default_payment_method_id text, user_submitted_reviews jsonb NOT NULL DEFAULT '[]'::jsonb, affiliate_submitted_content jsonb NOT NULL DEFAULT '{}'::jsonb, signed_order_forms jsonb NOT NULL DEFAULT '[]'::jsonb, review_supplemental_overlay jsonb NOT NULL DEFAULT '{}'::jsonb, slay_ticket_balance integer NOT NULL DEFAULT 0, CONSTRAINT profiles_pkey PRIMARY KEY (id));
CREATE TABLE public.psa_episode_entitlements (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, episode_id text NOT NULL, content_id text NOT NULL, access_source text NOT NULL DEFAULT 'slay-ticket'::text, redeemed_at timestamp with time zone NOT NULL DEFAULT now(), expires_at timestamp with time zone NOT NULL, total_watches integer NOT NULL DEFAULT 3, watches_used integer NOT NULL DEFAULT 0, pending_watch_seconds numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active'::text, slay_ticket_cost_at_redemption integer, created_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT psa_episode_entitlements_pkey PRIMARY KEY (id));
CREATE TABLE public.psa_message_usage (user_id uuid NOT NULL, month_key text NOT NULL DEFAULT ''::text, month_count integer NOT NULL DEFAULT 0, day_key text NOT NULL DEFAULT ''::text, day_count integer NOT NULL DEFAULT 0, updated_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT psa_message_usage_pkey PRIMARY KEY (user_id));
CREATE TABLE public.psa_watch_sessions (id uuid NOT NULL DEFAULT gen_random_uuid(), entitlement_id uuid NOT NULL, user_id uuid NOT NULL, episode_id text NOT NULL, started_at timestamp with time zone NOT NULL DEFAULT now(), last_active_at timestamp with time zone NOT NULL DEFAULT now(), actual_watched_seconds numeric NOT NULL DEFAULT 0, qualification_threshold_seconds numeric NOT NULL DEFAULT 0, qualified boolean NOT NULL DEFAULT false, consumed_watch_at timestamp with time zone, closed_at timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT psa_watch_sessions_pkey PRIMARY KEY (id));
CREATE TABLE public.reviews (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, email text NOT NULL, client_name text, rating integer NOT NULL, product text, review text, status text NOT NULL DEFAULT 'pending'::text, photos jsonb DEFAULT '[]'::jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), client_profile_photo_url text, videos integer NOT NULL DEFAULT 0, verified_purchase boolean NOT NULL DEFAULT false, video_urls jsonb NOT NULL DEFAULT '[]'::jsonb, CONSTRAINT reviews_pkey PRIMARY KEY (id), CONSTRAINT reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5))), CONSTRAINT reviews_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'published'::text, 'rejected'::text]))));
CREATE TABLE public.slay_ticket_transactions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, type text NOT NULL, amount integer NOT NULL, source text, description text NOT NULL DEFAULT ''::text, related_order_id text, related_content_id text, created_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT slay_ticket_transactions_pkey PRIMARY KEY (id), CONSTRAINT slay_ticket_transactions_type_check CHECK ((type = ANY (ARRAY['earned'::text, 'used'::text, 'purchased'::text, 'adjusted'::text, 'expired'::text]))));
DO $$ DECLARE t text; BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP; END $$;
-- psa_tool_events exists live with RLS enabled (no policies). Only its existence matters to M2 (ALTER ... ENABLE RLS);
-- its column shape is not replicated.
CREATE TABLE public.psa_tool_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz DEFAULT now());
ALTER TABLE public.psa_tool_events ENABLE ROW LEVEL SECURITY;
